func extractorForLockfile(lockfileName string) (filesystem.Extractor, bool) {
	for _, ext := range lockfileExtractors {
		if lockfileExtractorMapping[lockfileName] == ext.Name() {
			return ext, true
		}
	}

	return nil, false
}

if extractAs != "" {
	ext, ok := extractorForLockfile(extractAs)
	if !ok {
		return nil, fmt.Errorf("%w, requested %s", ErrExtractorNotFound, extractAs)
	}

	si, err := createScanInput(localPath, info)
	if err != nil {
		return nil, err
	}

	inv, err := ext.Extract(ctx, si)
	if err != nil {
		return nil, fmt.Errorf("(extracting as %s) %w", extractAs, err)
	}

	for i := range inv {
		inv[i].Extractor = ext
	}

	return inv, nil
}

